import React, { useState, useEffect, useCallback } from 'react';
import './CSS/SellerDashboard.css';
import { Link } from 'react-router-dom';
import axios from 'axios';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line, Doughnut } from 'react-chartjs-2';

// Register Chart.js Modules
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const API_BASE_URL = 'http://localhost:4000/api/seller';

const SellerDashboard = () => {
  const [activeTab, setActiveTab] = useState('inventory'); // 'inventory' | 'analytics' | 'status'
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Modals & Forms State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);

  // New Product Form State
  const [newProduct, setNewProduct] = useState({
    title: '',
    price: '',
    category: 'Electronics',
    stock: '',
    description: '',
    imageUrl: '',
    imageFile: null,
  });

  // Mock Data for Product Status & Tracking
  const [productStatuses] = useState([
    { id: 'PROD-101', name: 'Wireless Headphones', stock: 42, status: 'Shipped', trackingNo: 'TRK-982110', estimatedDelivery: 'Sep 20, 2026' },
    { id: 'PROD-102', name: 'Mechanical Keyboard', stock: 12, status: 'In Transit', trackingNo: 'TRK-441209', estimatedDelivery: 'Sep 21, 2026' },
    { id: 'PROD-103', name: 'Ergonomic Chair', stock: 0, status: 'Processing', trackingNo: 'Pending', estimatedDelivery: 'Sep 24, 2026' },
    { id: 'PROD-104', name: 'USB-C Charging Hub', stock: 5, status: 'Delivered', trackingNo: 'TRK-100293', estimatedDelivery: 'Sep 17, 2026' },
  ]);

  // Sales Analytics Metrics
  const [analyticsData, setAnalyticsData] = useState({
    totalRevenue: 0,
    totalOrders: 0,
    unitsSold: 0,
    avgOrderValue: 0,
    monthlyRevenue: [1200, 1900, 3000, 5000, 2400, 4800, 7200],
    categorySales: { Electronics: 45, Accessories: 25, Apparel: 15, Home: 15 },
  });

  // Fetch Inventory from Backend
  const fetchProducts = useCallback(async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/products`);
      if (response.data.success) {
        setProducts(response.data.products);
      }
    } catch (err) {
      console.error('Error loading inventory:', err);
    }
  }, []);

  // Fetch Analytics from Backend
  const fetchAnalytics = useCallback(async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/analytics`);
      if (response.data.success) {
        setAnalyticsData((prev) => ({ ...prev, ...response.data.data }));
      }
    } catch (err) {
      console.error('Error loading analytics:', err);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
    fetchAnalytics();
  }, [fetchProducts, fetchAnalytics]);

  // Chart Configurations for Analytics Tab
  const lineChartData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul'],
    datasets: [
      {
        label: 'Revenue ($)',
        data: analyticsData.monthlyRevenue || [1200, 1900, 3000, 5000, 2400, 4800, 7200],
        borderColor: '#4f46e5',
        backgroundColor: 'rgba(79, 70, 229, 0.1)',
        fill: true,
        tension: 0.4,
        pointBackgroundColor: '#4f46e5',
      },
    ],
  };

  const lineChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: (context) => ` Revenue: $${context.parsed.y.toLocaleString()}`,
        },
      },
    },
    scales: {
      y: { grid: { color: 'rgba(0, 0, 0, 0.05)' } },
      x: { grid: { display: false } },
    },
  };

  const doughnutChartData = {
    labels: Object.keys(analyticsData.categorySales),
    datasets: [
      {
        data: Object.values(analyticsData.categorySales),
        backgroundColor: ['#4f46e5', '#10b981', '#f59e0b', '#ec4899'],
        borderWidth: 2,
        borderColor: '#ffffff',
      },
    ],
  };

  const doughnutChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { position: 'bottom' },
    },
  };

  // Handle file selection and update state
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setNewProduct((prev) => ({
        ...prev,
        imageFile: file,
        imageUrl: URL.createObjectURL(file),
      }));
    }
  };

  // Handler: Add New Product
  const handleAddProductSubmit = async (e) => {
    e.preventDefault();

    if (!newProduct.title || newProduct.price === '' || newProduct.stock === '') {
      alert('Please fill in Title, Price, and Stock.');
      return;
    }

    try {
      const formData = new FormData();
      formData.append('title', newProduct.title);
      formData.append('price', Number(newProduct.price));
      formData.append('category', newProduct.category || 'Electronics');
      formData.append('stock', Number(newProduct.stock));
      formData.append('description', newProduct.description || '');

      if (newProduct.imageFile) {
        formData.append('image', newProduct.imageFile);
      }

      const response = await axios.post(`${API_BASE_URL}/products`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (response.data.success) {
        alert('Product published successfully!');
        setIsAddModalOpen(false);
        setNewProduct({
          title: '',
          price: '',
          category: 'Electronics',
          stock: '',
          description: '',
          imageUrl: '',
          imageFile: null,
        });
        fetchProducts(); // Refresh the list
      }
    } catch (err) {
      console.error('Submit Error:', err.response?.data);
      alert(err.response?.data?.message || 'Failed to add product');
    }
  };

  // Handler: Update Product Price and Stock
  const handleUpdateProductSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.put(`${API_BASE_URL}/products/${editingProduct._id || editingProduct.id}`, {
        price: parseFloat(editingProduct.price),
        stock: parseInt(editingProduct.stock, 10),
      });

      if (response.data.success) {
        alert('Product updated successfully!');
        setEditingProduct(null);
        fetchProducts();
      }
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to update product');
    }
  };

  // Handler: Delete Product
  const handleDeleteProduct = async (id) => {
    if (window.confirm('Are you sure you want to delete this listing?')) {
      try {
        const response = await axios.delete(`${API_BASE_URL}/products/${id}`);
        if (response.data.success) {
          fetchProducts();
        }
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to delete product');
      }
    }
  };

  // Search and Category Filter Logic
  const filteredProducts = products.filter((item) => {
    const productId = item._id || item.id || '';
    const matchesSearch =
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      productId.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === 'All' || item.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  // Calculate High-level Overview Metrics
  const totalItems = products.length;
  const lowStockItems = products.filter((p) => p.stock > 0 && p.stock <= 5).length;
  const outOfStockItems = products.filter((p) => p.stock === 0).length;
  const inventoryValue = products.reduce((sum, p) => sum + p.price * p.stock, 0);

  return (
    <div className="admin-wrapper">
      {/* Sidebar Navigation */}
      <aside className="admin-sidebar">
        <div className="sidebar-brand">
          <h2>HEX<span>STORE</span></h2>
          <span className="brand-subtitle">Seller Portal</span>
        </div>
        <nav className="sidebar-nav">
          <button className={activeTab === 'inventory' ? 'active' : ''} onClick={() => setActiveTab('inventory')}>
            Inventory & Products
          </button>
          <button className={activeTab === 'analytics' ? 'active' : ''} onClick={() => setActiveTab('analytics')}>
            Sales Analytics
          </button>
          <button className={activeTab === 'status' ? 'active' : ''} onClick={() => setActiveTab('status')}>
            Product Status & Tracking
          </button>
        </nav>
      </aside>

      {/* Main Panel Content */}
      <div className="admin-main">
        <header className="admin-header">
          <div className="header-search">
            <input
              type="text"
              placeholder="Search products by title or ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="header-right">
            <Link to="/" className="btn-storefront">View Storefront</Link>
            <div className="admin-profile-pill">
              <div className="profile-avatar bg-purple">S</div>
              <div className="profile-meta">
                <span className="profile-name">TechHub Electronics</span>
                <span className="profile-role">Verified Seller</span>
              </div>
            </div>
          </div>
        </header>

        <main className="admin-body">
          {/* TAB 1: INVENTORY & PRODUCTS */}
          {activeTab === 'inventory' && (
            <div className="tab-panel fade-in">
              {/* Overview Metric Row */}
              <div className="kpi-grid">
                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Total Listings</span></div>
                    <div className="kpi-body"><span className="kpi-number">{totalItems}</span></div>
                  </div>
                  <div className="kpi-side-bar bg-blue"></div>
                </div>

                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Low Stock Alerts</span></div>
                    <div className="kpi-body"><span className="kpi-number text-warning">{lowStockItems}</span></div>
                  </div>
                  <div className="kpi-side-bar bg-purple"></div>
                </div>

                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Out of Stock</span></div>
                    <div className="kpi-body"><span className="kpi-number text-danger">{outOfStockItems}</span></div>
                  </div>
                  <div className="kpi-side-bar bg-green"></div>
                </div>

                <div className="kpi-card kpi-primary hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title text-light">Total Inventory Value</span></div>
                    <div className="kpi-body"><span className="kpi-number text-light">${inventoryValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
                  </div>
                </div>
              </div>

              {/* Product Inventory Table */}
              <div className="split-main-card full-width">
                <div className="card-header-flex">
                  <div>
                    <h3>Product Inventory</h3>
                    <p className="card-subtitle">Manage price listings, update available stock, and add items</p>
                  </div>
                  <div style={{ display: 'flex', gap: '12px' }}>
                    <select
                      className="category-filter-select"
                      value={categoryFilter}
                      onChange={(e) => setCategoryFilter(e.target.value)}
                    >
                      <option value="All">All Categories</option>
                      <option value="Electronics">Electronics</option>
                      <option value="Accessories">Accessories</option>
                      <option value="Apparel">Apparel</option>
                      <option value="Home">Home</option>
                    </select>
                    <button className="btn-primary" onClick={() => setIsAddModalOpen(true)}>
                      + Add New Product
                    </button>
                  </div>
                </div>

                <div className="table-responsive">
                  <table className="enhanced-table">
                    <thead>
                      <tr>
                        <th>Product Info</th>
                        <th>Category</th>
                        <th>Price</th>
                        <th>Available Stock</th>
                        <th>Status</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredProducts.map((product) => {
                        const productId = product._id || product.id;
                        return (
                          <tr key={productId}>
                            <td>
                              <div className="user-cell">
                                <div className="store-avatar-box">
                                  {product.imageUrl ? (
                                    <img src={product.imageUrl} alt={product.title} style={{ width: '100%', height: '100%', borderRadius: '4px', objectFit: 'cover' }} />
                                  ) : (
                                    product.title.charAt(0)
                                  )}
                                </div>
                                <div>
                                  <strong className="user-name">{product.title}</strong>
                                  <span className="user-subtext">ID: {productId}</span>
                                </div>
                              </div>
                            </td>
                            <td>{product.category}</td>
                            <td><strong className="text-dark">${product.price.toFixed(2)}</strong></td>
                            <td>
                              <span className={product.stock <= 5 ? 'text-danger fw-bold' : ''}>
                                {product.stock} units
                              </span>
                            </td>
                            <td>
                              <span className={`badge-pill status-${product.stock > 0 ? 'active' : 'blocked'}`}>
                                <span className="status-indicator-dot"></span>
                                {product.stock > 0 ? 'In Stock' : 'Out of Stock'}
                              </span>
                            </td>
                            <td>
                              <div style={{ display: 'flex', gap: '8px' }}>
                                <button className="btn-table-action" onClick={() => setEditingProduct({ ...product })}>
                                  Edit Price/Stock
                                </button>
                                <button className="btn-control-toggle danger" onClick={() => handleDeleteProduct(productId)}>
                                  Delete
                                </button>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                      {filteredProducts.length === 0 && (
                        <tr>
                          <td colSpan="6" style={{ textAlign: 'center', padding: '24px', color: '#777' }}>
                            No products found in inventory.
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {/* TAB 2: SALES ANALYTICS */}
          {activeTab === 'analytics' && (
            <div className="tab-panel fade-in">
              <div className="kpi-grid">
                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Total Revenue</span></div>
                    <div className="kpi-body">
                      <span className="kpi-number text-success">
                        ${analyticsData.totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                  </div>
                  <div className="kpi-side-bar bg-green"></div>
                </div>

                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Total Orders</span></div>
                    <div className="kpi-body"><span className="kpi-number">{analyticsData.totalOrders}</span></div>
                  </div>
                  <div className="kpi-side-bar bg-blue"></div>
                </div>

                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Units Sold</span></div>
                    <div className="kpi-body"><span className="kpi-number">{analyticsData.unitsSold}</span></div>
                  </div>
                  <div className="kpi-side-bar bg-purple"></div>
                </div>

                <div className="kpi-card hover-lift">
                  <div className="kpi-content">
                    <div className="kpi-header"><span className="kpi-title">Avg Order Value</span></div>
                    <div className="kpi-body">
                      <span className="kpi-number text-dark">
                        ${analyticsData.avgOrderValue ? analyticsData.avgOrderValue.toFixed(2) : '0.00'}
                      </span>
                    </div>
                  </div>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px', marginTop: '24px' }}>
                <div className="split-main-card" style={{ background: '#fff', borderRadius: '12px', padding: '20px' }}>
                  <h3>Revenue Performance Overview</h3>
                  <p className="card-subtitle">Monthly revenue progression trajectory</p>
                  <div style={{ height: '300px', marginTop: '16px' }}>
                    <Line data={lineChartData} options={lineChartOptions} />
                  </div>
                </div>

                <div className="split-main-card" style={{ background: '#fff', borderRadius: '12px', padding: '20px' }}>
                  <h3>Sales by Category</h3>
                  <p className="card-subtitle">Percentage breakdown per sector</p>
                  <div style={{ height: '260px', marginTop: '16px' }}>
                    <Doughnut data={doughnutChartData} options={doughnutChartOptions} />
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: PRODUCT STATUS & TRACKING */}
          {activeTab === 'status' && (
            <div className="tab-panel fade-in">
              <div className="split-main-card full-width">
                <div className="card-header-flex">
                  <div>
                    <h3>Product Order Status & Tracking</h3>
                    <p className="card-subtitle">Monitor stock levels, shipping stages, and carrier delivery updates</p>
                  </div>
                </div>

                <div className="table-responsive">
                  <table className="enhanced-table">
                    <thead>
                      <tr>
                        <th>Product Name</th>
                        <th>Available Stock</th>
                        <th>Fulfillment Status</th>
                        <th>Tracking ID</th>
                        <th>Est. Delivery</th>
                      </tr>
                    </thead>
                    <tbody>
                      {productStatuses.map((item) => (
                        <tr key={item.id}>
                          <td>
                            <strong>{item.name}</strong>
                            <br />
                            <small className="user-subtext">ID: {item.id}</small>
                          </td>
                          <td>
                            <span className={item.stock === 0 ? 'text-danger fw-bold' : ''}>
                              {item.stock} units
                            </span>
                          </td>
                          <td>
                            <span className={`badge-pill status-${item.status.toLowerCase().replace(' ', '-')}`}>
                              <span className="status-indicator-dot"></span>
                              {item.status}
                            </span>
                          </td>
                          <td><code>{item.trackingNo}</code></td>
                          <td>{item.estimatedDelivery}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Add New Product Modal */}
      {isAddModalOpen && (
        <div className="modal-backdrop" onClick={() => setIsAddModalOpen(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h3>Add New Product</h3>
                <span className="modal-subtitle">List a new item in your store inventory</span>
              </div>
              <button className="btn-modal-close" onClick={() => setIsAddModalOpen(false)}>&times;</button>
            </div>
            <form onSubmit={handleAddProductSubmit} className="settings-form" style={{ marginTop: '16px' }}>
              <div className="setting-field">
                <label htmlFor="productTitle">Product Title *</label>
                <input
                  id="productTitle"
                  type="text"
                  required
                  value={newProduct.title}
                  onChange={(e) => setNewProduct({ ...newProduct, title: e.target.value })}
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="setting-field">
                  <label htmlFor="productPrice">Price ($) *</label>
                  <input
                    id="productPrice"
                    type="number"
                    step="0.01"
                    required
                    value={newProduct.price}
                    onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })}
                  />
                </div>
                <div className="setting-field">
                  <label htmlFor="productStock">Initial Stock *</label>
                  <input
                    id="productStock"
                    type="number"
                    required
                    value={newProduct.stock}
                    onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })}
                  />
                </div>
              </div>

              <div className="setting-field">
                <label htmlFor="productCategory">Category</label>
                <select
                  id="productCategory"
                  value={newProduct.category}
                  onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })}
                >
                  <option value="Electronics">Electronics</option>
                  <option value="Accessories">Accessories</option>
                  <option value="Apparel">Apparel</option>
                  <option value="Home">Home</option>
                </select>
              </div>

              <div className="setting-field">
                <label htmlFor="product-image">Product Image</label>
                <div className="custom-file-upload">
                  <input 
                    type="file" 
                    id="product-image" 
                    accept="image/*" 
                    onChange={handleImageChange} 
                  />
                  <label htmlFor="product-image" className="upload-box-content">
                    <svg className="upload-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                    </svg>
                    <span>{newProduct.imageFile ? newProduct.imageFile.name : "Click to upload or drag image here"}</span>
                  </label>
                </div>
              </div>

              <div className="setting-field">
                <label htmlFor="productDesc">Description</label>
                <textarea
                  id="productDesc"
                  rows="3"
                  style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={newProduct.description}
                  onChange={(e) => setNewProduct({ ...newProduct, description: e.target.value })}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                <button type="button" className="btn-outline-sm" onClick={() => setIsAddModalOpen(false)}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary">
                  Publish Product
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Price / Inventory Modal */}
      {editingProduct && (
        <div className="modal-backdrop" onClick={() => setEditingProduct(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h3>Update Product: {editingProduct.title}</h3>
                <span className="modal-subtitle">Update pricing and manage stock levels</span>
              </div>
              <button className="btn-modal-close" onClick={() => setEditingProduct(null)}>&times;</button>
            </div>
            <form onSubmit={handleUpdateProductSubmit} className="settings-form" style={{ marginTop: '16px' }}>
              <div className="setting-field">
                <label htmlFor="editPrice">Unit Price ($)</label>
                <input
                  id="editPrice"
                  type="number"
                  step="0.01"
                  required
                  value={editingProduct.price}
                  onChange={(e) => setEditingProduct({ ...editingProduct, price: e.target.value })}
                />
              </div>

              <div className="setting-field">
                <label htmlFor="editStock">Available Stock Count</label>
                <input
                  id="editStock"
                  type="number"
                  required
                  value={editingProduct.stock}
                  onChange={(e) => setEditingProduct({ ...editingProduct, stock: e.target.value })}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                <button type="button" className="btn-outline-sm" onClick={() => setEditingProduct(null)}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary">
                  Save Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SellerDashboard;
